        table = [(100, 50), (160, 110)]
        for t in (99, 161):
            with self.assertRaises(ValueError):
                depth_at(table, t)
        for bad in ([], [(0, 1)], [(5, 1), (5, 2)], [(9, 1), (3, 2)]):
            with self.assertRaises(ValueError):
                depth_at(bad, 5)
            with self.assertRaises(ValueError):
                safe_windows(bad, 1, 0)

