        self.assertEqual(delay(base, "a", "e"), ["b", "c", "d", "e", "a"])
        self.assertEqual(delay(base, "e", "a"), ["a", "e", "b", "c", "d"])
        self.assertEqual(delay(base, "d", "b"), ["a", "b", "d", "c", "e"])
        self.assertEqual(delay(base, "c", "b"), base)
        self.assertEqual(base, ["a", "b", "c", "d", "e"])

