import random
from fractions import Fraction
from tidal import best_slot, depth_at, safe_windows


def oracle_depth(table, t):
    for (t0, h0), (t1, h1) in zip(table, table[1:]):
        if t0 <= t <= t1:
            return Fraction(h0) + Fraction(h1 - h0, t1 - t0) * (t - t0)


