    def test_days_left(self):
        self.assertEqual(days_left(FROST, CROPS[0], date(2024, 4, 10)), 5)

    def test_next_opening(self):
        self.assertEqual(next_opening(FROST, CROPS, date(2024, 4, 12)), ("beans", date(2024, 4, 27)))


