"""Fare rules of an island ferry."""

__all__ = ["passenger_fare", "vehicle_fare", "fare"]


def passenger_fare(zones):
    if zones < 1:
        raise ValueError("zones must be at least 1")
    if zones == 1:
        return 450
    return 700 + 175 * (zones - 2)


def vehicle_fare(length_dm):
    if length_dm is None:
        return 0
    if length_dm <= 0:
        raise ValueError("vehicle length must be positive")
    if length_dm <= 30:
        return 1200
    if length_dm <= 55:
        return 2600
    if length_dm <= 80:
        return 4800
    started = -(-(length_dm - 80) // 10)
    return 4800 + 900 * started


def fare(zones, ages, length_dm=None, depart=(9, 0)):
    adult = passenger_fare(zones)
    pax = 0
    for age in ages:
        if age < 0:
            raise ValueError("negative age")
        if age >= 16:
            pax += adult
        elif age >= 5:
            pax += (adult + 1) // 2
    minute = depart[0] * 60 + depart[1]
    if 10 * 60 <= minute < 15 * 60:
        pax = (pax * 85 + 50) // 100
    total = pax + vehicle_fare(length_dm)
    return -(-total // 5) * 5

solution.src/initiative/core.py:
"""Turn order for a skirmish tracker, with house rules."""

__all__ = ["order", "turns", "delay", "drop"]


def order(combatants):
    names = [c["name"] for c in combatants]
    if len(set(names)) != len(names):
        raise ValueError("duplicate name")
    ranked = sorted(combatants, key=lambda c: (-c["roll"], -c["dex"], c["name"].lower(), c["name"]))
    return [c["name"] for c in ranked]


def turns(combatants, rounds):
    sequence = order(combatants)
    surprised = {c["name"] for c in combatants if c.get("surprised")}
    out = []
    for r in range(1, rounds + 1):
        for name in sequence:
            if r == 1 and name in surprised:
                continue
            out.append((r, name))
    return out


def delay(order_list, name, after):
    if name == after or name not in order_list or after not in order_list:
        raise ValueError("cannot delay")
    rest = [n for n in order_list if n != name]
    i = rest.index(after)
    return rest[: i + 1] + [name] + rest[i + 1 :]


def drop(order_list, name, current):
    if name not in order_list:
        raise ValueError("no such combatant")
    idx = order_list.index(name)
    rest = [n for n in order_list if n != name]
    if not rest:
        return [], 0
    if idx < current:
        current -= 1
    elif idx == current and current >= len(rest):
        current = 0
    return rest, current

solution.src/quorum/core.py:
"""Meeting vote tally with proxies."""

__all__ = ["tally"]


def tally(members, ballots, proxies, quorum_pct=50, chair=None):
    mem = set(members)
    votes = {m: v for m, v in ballots.items() if m in mem}
    counted = list(votes.values())
    carried = {}
    seen_givers = set()
    for giver, holder in proxies:
        if giver not in mem or holder not in mem:
            continue
        if giver in seen_givers:
            continue
        seen_givers.add(giver)
        if giver in votes or holder not in votes:
            continue
        if carried.get(holder, 0) >= 2:
            continue
        carried[holder] = carried.get(holder, 0) + 1
        counted.append(votes[holder])
    yes, no, abstain = counted.count("yes"), counted.count("no"), counted.count("abstain")
    needed = -(-len(mem) * quorum_pct // 100)
    quorum = len(counted) >= needed
    if not quorum:
        result = "no-quorum"
    elif yes > no:
        result = "passed"
    elif no > yes:
        result = "rejected"
    else:
        c = votes.get(chair) if chair is not None else None
        result = "passed" if c == "yes" else "rejected" if c == "no" else "tied"
    return {"yes": yes, "no": no, "abstain": abstain, "counted": len(counted), "quorum": quorum, "result": result}

